const http = require('http');
const url = require('url');
const crypto = require('crypto');

// Custom serialization library for cache entries
class CacheSerializer {
  constructor(options = {}) {
    this.delimiter = options.delimiter || '\x1f';
    this.encoding = options.encoding || 'utf-8';
    this.maxKeyLength = options.maxKeyLength || 256;
    this.hmacSecret = options.hmacSecret || crypto.randomBytes(32);
  }

  // Serialize a cache entry into a storable format
  serialize(key, value, metadata = {}) {
    const timestamp = Date.now();
    const entry = {
      k: this._normalizeKey(key),
      v: value,
      m: metadata,
      t: timestamp
    };
    const payload = JSON.stringify(entry);
    const hmac = this._computeHmac(payload);
    return `${hmac}${this.delimiter}${payload}`;
  }

  // Deserialize a stored cache entry
  deserialize(raw) {
    const delimIdx = raw.indexOf(this.delimiter);
    if (delimIdx === -1) throw new Error('Invalid cache entry format');
    const hmac = raw.slice(0, delimIdx);
    const payload = raw.slice(delimIdx + 1);
    if (!this._verifyHmac(payload, hmac)) {
      throw new Error('Cache entry integrity check failed');
    }
    return JSON.parse(payload);
  }

  _normalizeKey(key) {
    if (typeof key !== 'string') key = String(key);
    if (key.length > this.maxKeyLength) {
      key = key.slice(0, this.maxKeyLength);
    }
    // Normalize unicode and sanitize control characters
    return key.normalize('NFC').replace(/[\x00-\x1f\x7f]/g, '');
  }

  _computeHmac(data) {
    return crypto.createHmac('sha256', this.hmacSecret)
      .update(data)
      .digest('hex');
  }

  _verifyHmac(data, expectedHmac) {
    const computed = this._computeHmac(data);
    const computedBuf = Buffer.from(computed, 'hex');
    let expectedBuf;
    try {
      expectedBuf = Buffer.from(expectedHmac, 'hex');
    } catch (e) {
      return false;
    }
    // Guard against length mismatch which would make timingSafeEqual throw
    if (computedBuf.length !== expectedBuf.length) {
      return false;
    }
    return crypto.timingSafeEqual(computedBuf, expectedBuf);
  }
}

// Response builder that constructs HTTP responses for the reverse proxy
class ResponseBuilder {
  constructor(serializer) {
    this.serializer = serializer;
    this.defaultHeaders = {
      'X-Cache-Engine': 'NodeCacheV2',
      'Content-Type': 'application/json'
    };
  }

  // Build a cache status header value from the cache entry
  buildCacheStatusHeader(cacheKey, hit) {
    const status = hit ? 'HIT' : 'MISS';
    // Include the normalized cache key in the diagnostic header
    // for debugging by upstream reverse proxy
    return `${status}; key="${cacheKey}"`;
  }

  // Construct the full response with headers
  buildResponse(res, statusCode, body, cacheKey, cacheHit) {
    const headers = { ...this.defaultHeaders };
    headers['X-Cache-Status'] = this.buildCacheStatusHeader(cacheKey, cacheHit);
    headers['X-Request-Id'] = crypto.randomUUID();

    res.writeHead(statusCode, headers);
    res.end(JSON.stringify(body));
  }
}

// In-memory cache store
const cache = new Map();
const serializer = new CacheSerializer({ maxKeyLength: 512 });
const responseBuilder = new ResponseBuilder(serializer);

// Maximum allowed request body size to prevent memory-exhaustion DoS
const MAX_BODY_SIZE = 1 * 1024 * 1024; // 1 MB

// Middleware: extract and validate the cache key from request
function extractCacheKey(req) {
  const parsed = url.parse(req.url, true);
  const rawKey = parsed.query.key || parsed.pathname;
  // The key goes through normalization in the serializer
  return serializer._normalizeKey(rawKey);
}

// Main request handler
function handleRequest(req, res) {
  try {
    if (req.method === 'GET') {
      const cacheKey = extractCacheKey(req);
      const stored = cache.get(cacheKey);

      if (stored) {
        const entry = serializer.deserialize(stored);
        responseBuilder.buildResponse(res, 200, { data: entry.v }, cacheKey, true);
      } else {
        responseBuilder.buildResponse(res, 404, { error: 'not found' }, cacheKey, false);
      }
    } else if (req.method === 'PUT') {
      let body = '';
      let size = 0;
      let aborted = false;
      req.on('data', chunk => {
        if (aborted) return;
        size += chunk.length;
        if (size > MAX_BODY_SIZE) {
          aborted = true;
          res.writeHead(413, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Payload too large' }));
          req.destroy();
          return;
        }
        body += chunk;
      });
      req.on('end', () => {
        if (aborted) return;
        try {
          const parsed = JSON.parse(body);
          const cacheKey = extractCacheKey(req);
          const serialized = serializer.serialize(cacheKey, parsed.value, parsed.metadata);
          cache.set(cacheKey, serialized);
          responseBuilder.buildResponse(res, 201, { stored: true }, cacheKey, false);
        } catch (e) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Invalid request body' }));
        }
      });
    } else {
      res.writeHead(405, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Method not allowed' }));
    }
  } catch (e) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Internal server error' }));
  }
}

const server = http.createServer(handleRequest);
const PORT = process.env.PORT || 3000;
server.listen(PORT, '127.0.0.1', () => {
  console.log(`Cache service listening on port ${PORT}`);
});

module.exports = { CacheSerializer, ResponseBuilder, handleRequest };
